mapper.select:
select count(1) c from alert_message_active ama right join (
	select id from asset_asset aa where cabinet_id = #{id}
) aac on ama.asset_id = aac.id


select conf.name as priority, IFNULL(cnt.c,0) as num from alert_severity_conf conf 
left join (
	SELECT
		severity_id,
		count(1) c
	FROM
		alert_message_active
	WHERE 


		        asset_id = #{id}


		        rule_id = #{id}


		        project_id = #{id}


		        module_id = #{id}


		        endpoint_id = #{id}


		        dc_id = #{id}


    GROUP BY severity_id
) cnt on conf.id = cnt.severity_id
order by conf.weight

